def select_node(node):
    global NODE, HOST, UNIT, RUNTIME, FC_WORK, OLD_UNITS
    if node not in ('node-a', 'node-b'):
        raise ValueError('Explicit node-a/node-b required')
    NODE = node
    HOST = 'server1' if node == 'node-a' else 'agent1'
    suffix = 'a' if node == 'node-a' else 'b'
    UNIT = 'jwk-aenv-dsec-hostfile-v1-' + node + '.service'
    RUNTIME = ROOT / ('r/dsec-hostfile-' + suffix + '-v1')
    FC_WORK = ROOT / ('r/fc-dsec-hostfile-' + suffix + '-v1')
    OLD_UNITS = ('jwk-aenv-ae9c626-' + node + '.service',
                 'jwk-aenv-ub-b019f27-' + node + '.service',
                 'jwk-aenv-native-fe63038-' + node + '.service',
                 'ubsmd.service', 'ubse.service')


select_node('node-a')


def need(ok,message):
    if not ok: raise RuntimeError(message)


def own(path,limit=512*1024**2):
    p=Path(path)
    need(p.is_absolute() and p.is_relative_to(ROOT) and p.resolve(strict=True)==p,'Input path is missing, redirected or outside project')
    m=p.lstat();need(stat.S_ISREG(m.st_mode) and m.st_uid==1204 and m.st_nlink==1 and m.st_size<=limit,'Unexpected input file owner/type/size')
    with p.open('rb') as f:
        before=os.fstat(f.fileno());raw=f.read(limit+1);after=os.fstat(f.fileno())
    stamp=lambda x:(x.st_dev,x.st_ino,x.st_size,x.st_mtime_ns)
    need(stamp(before)==stamp(after)==stamp(p.stat()) and len(raw)==before.st_size,'Input changed during read')
    return raw


def digest(raw): return hashlib.sha256(raw).hexdigest()
def read_json(path): return json.loads(own(path,2*1024**2))


def binary(path,expected):
    raw=own(path)
    need(isinstance(expected,str) and re.fullmatch(r'[0-9a-f]{64}',expected) and digest(raw)==expected,'Binary checksum differs')
    need(len(raw)>=64 and raw[:6]==b'\x7fELF\x02\x01' and struct.unpack_from('<H',raw,18)[0]==183,'Binary is not little-endian AArch64 ELF64')
    return {'sha256':expected,'bytes':len(raw)}


def make_module(definition):
    raw=base64.b64decode(BASE_SOURCE_B64,validate=True)
    need(digest(raw)==BASE_SOURCE_SHA,'Audited deployment library differs')
    m=types.ModuleType('native_audited_deployment');m.__file__=str(D/'libexec/native_base.py')
    exec(compile(raw,m.__file__,'exec'),m.__dict__)
    m.D=D;m.RUNTIME=RUNTIME;m.UNIT=UNIT;m.PORT=definition.get('apiPort',18082);m.REVISION='aenv-dsec-hostfile-v1'
    need(type(m.PORT) is int and 18082<=m.PORT<=18089,'Unexpected new-service port')
    m.COMMIT=COMMIT;m.STATUS_PREFIX='NATIVE_V4';m.BINARIES=definition['binaries']
    m.NODE=NODE;m.EXPECTED_HOST=HOST;m.OLD_UNIT=OLD_UNITS[0];m.BASE=BASE
    m.LAUNCHER=D/'libexec/native_service.py';m.config_text=lambda:definition['config']
    original_environment=m.environment
    def environment():
        env=original_environment()
        for key in ('AENV_DIRECT_MEMORY_BINDING','AENV_UB_MEMORY_REPLICAS','AENV_UB_ROOTFS_REPLICAS','AENV_DIRECT_ROOTFS_BINDING'):
            env.pop(key,None)
        if definition.get('rootfsBinding'):
            env['AENV_DIRECT_ROOTFS_BINDING']=definition['rootfsBinding']['path']
        return env
    m.environment=environment
    original_run=m.run
    def run(args,*rest,**kw):
        args=list(args)
        if str(args[0])==str(D/'cli/bin/aenv-ub'): args[0]=D/'cli/bin/aenv-native'
        return original_run(args,*rest,**kw)
    m.run=run
    return m



def select_api_port():
    import errno
    busy=[]
    for port in range(18082,18090):
        try:
            with socket.socket() as probe:probe.bind(('127.0.0.1',port))
        except OSError as error:
            if error.errno!=errno.EADDRINUSE:raise
            busy.append(port)
            continue
        return port,busy
    raise RuntimeError('No free new-service loopback port in 18082..18089; occupied listeners preserved')

