def old_state(m):
    result={}
    for unit in OLD_UNITS:
        row=m.properties(unit)
        pid=int(row.get('MainPID','0'))
        ticks=Path('/proc/'+str(pid)+'/stat').read_text().rsplit(')',1)[1].split()[19] if pid>1 else None
        result[unit]=[row.get('LoadState'),row.get('ActiveState'),pid,ticks]
    need(result[OLD_UNITS[0]][1]=='active' and result[OLD_UNITS[0]][2]>1,'Original service must be active; no recovery attempted')
    m.http_health(18080)
    return result


def adapter(definition):
    # Reuses only the audited library, with a fixed immutable new-service definition.
    return ("import base64,hashlib,json,sys\nfrom pathlib import Path\n"+
            "p=Path("+repr(str(D/'libexec/native_prepare.py'))+");raw=p.read_bytes()\n"+
            "if hashlib.sha256(raw).hexdigest()!="+repr(definition['prepareSourceSha256'])+":raise RuntimeError('Native adapter dependency changed')\n"+
            "scope={'__name__':'native_adapter','__file__':str(p)};exec(compile(raw,str(p),'exec'),scope)\n"+
            "scope['runtime_entry']("+repr(definition)+",sys.argv[1:])\n").encode()


def runtime_entry(definition,argv):
    select_node(definition['node'])
    need(argv and argv[0] in ('inside','proxy-inside','proxy-host','health'),'Unexpected runtime adapter mode')
    m=make_module(definition);m.identity()
    need(digest(own(D/'definition-native.json',1024**2))==definition['definitionSha256'],'Native definition changed')
    if definition.get('rootfsBinding'):
        need(digest(own(definition['rootfsBinding']['path'],2*1024**2))==definition['rootfsBinding']['sha256'],'Native rootfs binding changed')
    if argv[0]=='inside':
        try:m.inside()
        except BaseException:
            import traceback
            with (D/'logs/launcher.log').open('a') as log:traceback.print_exc(file=log)
            raise
        return
    if argv[0].startswith('proxy-'):
        import asyncio
        asyncio.run(m.proxy(argv[0].split('-',1)[1]));return
    m.no_caps();before=old_state(m)
    result=m.health('--post-disconnect' in argv)
    need(old_state(m)==before,'An existing service changed during native health')
    result.update(activate='source '+str(D/'cli/env.sh'),CLI=str(D/'cli/bin/aenv-native'),
        existing_services_unchanged=True,nativeGuestBindingsConfigured=bool(definition.get('rootfsBinding')),
        Guest_or_DAX_acceptance=False,SDK_called=False)
    print('BEGIN_NATIVE_HEALTH_REPORT');print(json.dumps(result,indent=2));print('END_NATIVE_HEALTH_REPORT')


