def coordinated_artifacts(report_path):
    expected=BUILD_RECEIPT
    raw=own(report_path,2*1024**2);value=json.loads(raw)
    for key in ('revision','status','release','artifacts','SDK_called','Guest_created',
                'servicesChanged','embeddedPolicySha256','policySourceSha256'):
        need(value.get(key)==expected[key],'Completed Host-file build differs: '+key)
    need(set(value.get('phases',{}))==set(expected['phases']) and
         all(row.get('exitCode')==0 for row in value['phases'].values()),'Incomplete build/test phases')
    root=ROOT/'builds/dsec-hostfile-release-v2/artifacts'
    result=dict(value)
    result['artifactPaths']={name:str(root/name) for name in expected['artifacts']}
    for name,row in expected['artifacts'].items():
        need(row['path']==str(root/name) and (root/name).stat().st_size==row['bytes'],'Artifact length/path differs')
        binary(root/name,row['sha256'])
    result['componentProvenance']={name:COMMIT for name in expected['artifacts']}
    result['componentProvenance']['buildReceiptSha256']=digest(raw)
    return result,root



def prepare(args):
    select_node(args.node)
    need(sys.platform=='linux' and socket.gethostname()==HOST and os.uname().machine=='aarch64','Use the declared ARM64 node')
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk without sudo')
    caps=dict(line.split(':',1) for line in Path('/proc/self/status').read_text().splitlines() if ':' in line)
    need(all(int(caps[k].strip(),16)==0 for k in ('CapInh','CapPrm','CapEff','CapAmb')),'Capability-free preparation required')
    core,artifact_root=coordinated_artifacts(Path(args.core_report))
    binaries={name:core['artifacts'][name]['sha256'] for name in ('server','aenv','uvm-ublk-daemon','aenv-native-fd-verify')}
    firecracker=artifact_root/'firecracker'
    fc_artifacts=core['artifacts']
    tools=read_json(args.tools_report)
    need(tools.get('status')=='PRIVATE_TOOLS_IMAGE_PREPARED_NOT_GUEST_ACCEPTANCE' and tools.get('mode')=='runtime'
         and tools.get('originalUnchanged') is True and tools.get('lowerFilesystem')=='ext4','New runtime Guest tools are not ready')
    tools_image=Path(args.tools_image or tools['imagePath']);tools_bytes=own(tools_image)
    need(digest(tools_bytes)==tools['image']['sha256'],'New tools image differs')
    definition={'node':NODE,'binaries':binaries,'config':configuration(tools['toolsVersion']),'rootfsBinding':None,'componentProvenance':core['componentProvenance']}
    if args.rootfs_binding:
        binding=own(args.rootfs_binding,2*1024**2)
        need(re.fullmatch(r'[0-9a-f]{64}',args.binding_sha256 or '') and digest(binding)==args.binding_sha256,'Explicit rootfs binding pin differs')
        value=json.loads(binding)
        need(set(value)=={'catalogVersion','bindings'} and value['catalogVersion']==1 and len(value['bindings'])==4,
             'Exactly four native rootfs bindings required')
        sources=set()
        for item in value['bindings']:
            need(item.get('version')==5 and item.get('lowerFilesystem')=='ext4' and item.get('sourceImage') not in sources,
                 'Invalid or duplicate native rootfs source')
            sources.add(item['sourceImage'])
            runtime=item.get('deviceRuntime',{})
            need(runtime.get('firecrackerSha256')=='sha256:'+fc_artifacts['firecracker']['sha256']
                 and runtime.get('verifierSha256')=='sha256:'+binaries['aenv-native-fd-verify']
                 and runtime.get('verifier')==str(D/'bin/aenv-native-fd-verify'),'Rootfs binding must use this coordinated FC/verifier')
        definition['rootfsBinding']={'path':str(Path(args.rootfs_binding)),'sha256':args.binding_sha256}
    m=make_module(definition);m.identity();m.no_caps()
    old=old_state(m)
    for path in (D,RUNTIME,FC_WORK):
        need(path.resolve()==path and not path.exists() and not path.is_symlink(),'New deployment/runtime/work path already exists or redirected; preserved')
    need(digest(own(BASE/'deps/kernel/vmlinux-6.1.175/vmlinux.bin'))==KERNEL_SHA,'Original Guest kernel differs')
    port,busy=select_api_port()
    definition['apiPort']=port
    definition['portSelection']={'candidates':list(range(18082,18090)),'occupiedPortsPreserved':busy}
    print('NEW_NATIVE_API_PORT='+str(port)+' OCCUPIED_PORTS_PRESERVED='+json.dumps(busy),flush=True)
    prepare_raw=Path(__file__).read_bytes();definition['prepareSourceSha256']=digest(prepare_raw)
    public_definition={k:v for k,v in definition.items() if k!='prepareSourceSha256'}
    definition_raw=(json.dumps(public_definition,indent=2,sort_keys=True)+'\n').encode()
    definition['definitionSha256']=digest(definition_raw)
    m=make_module(definition);m.ARTIFACTS=artifact_root;m.ARTIFACT_PATHS={k:Path(v) for k,v in core['artifactPaths'].items()}
    original_inputs=m.selected_inputs
    def selected():
        items=original_inputs()
        replacements={'bin/server':(Path(core['artifactPaths']['server']),binaries['server'],0o750),
                      'bin/uvm-ublk-daemon':(Path(core['artifactPaths']['uvm-ublk-daemon']),binaries['uvm-ublk-daemon'],0o750),
                      'deps/firecracker/1.15.1-patch-v3/firecracker':(firecracker,fc_artifacts['firecracker']['sha256'],0o750),
                      'deps/tools/0.1.1/tools.ext4':(tools_image,tools['image']['sha256'],0o640)}
        result=[]
        for relative,path,mode,expected in items:
            if relative.as_posix() in replacements:
                path,expected,mode=replacements[relative.as_posix()]
            result.append((relative,path,mode,expected))
        return result
    m.selected_inputs=selected
    def cli_files(key):
        for folder in ('cli/cache','cli/tmp'):m.mkdir(D/folder)
        script=('#!/bin/sh\nexport XDG_CONFIG_HOME="'+str(D/'cli/config')+'"\nexport XDG_CACHE_HOME="'+str(D/'cli/cache')+'"\nexport TMPDIR="'+str(D/'cli/tmp')+'"\nexport LD_LIBRARY_PATH="'+str(D/'native/lib')+':'+str(D/'native/fallback/lib')+'"\nunset http_proxy https_proxy HTTP_PROXY HTTPS_PROXY all_proxy ALL_PROXY\nexport NO_PROXY="127.0.0.1,localhost,::1"\nexport no_proxy="$NO_PROXY"\nexec "'+str(D/'bin/aenv')+'" "$@"\n').encode()
        m.put(D/'cli/bin/aenv-native',script,0o700)
        m.put(D/'cli/config/aenv/credentials',('url = "http://127.0.0.1:'+str(definition['apiPort'])+'"\napi_key = '+json.dumps(key)+'\n').encode())
        m.put(D/'cli/env.sh',('export PATH="'+str(D/'cli/bin')+':$PATH"\nhash -r\n').encode())
    m.cli_files=cli_files
    def stage_launcher():
        m.put(D/'libexec/native_base.py',base64.b64decode(BASE_SOURCE_B64,validate=True))
        m.put(D/'libexec/native_prepare.py',prepare_raw)
        m.put(D/'definition-native.json',definition_raw)
        m.put(D/'cohort.lock',b'')
        m.dump(D/'cohort-state.json',{'version':1,'phase':'prepared','openRequests':[],'sandboxIds':[],'outcomeUncertain':False})
        m.put(m.LAUNCHER,adapter(definition))
