CONTROL_SOURCE_B64 = ''
CONTROL_SOURCE_SHA = '281c1118df1228b3c866bd77ab59c946ca005f9f7e3ae6485a7988fef51e7649'


def control_plan(mode):
    raw=own(D/'definition-native.json',1024**2)
    definition=json.loads(raw)
    need(definition.get('node')==NODE,'Installed deployment belongs to another node')
    definition['definitionSha256']=digest(raw)
    definition['prepareSourceSha256']=digest(own(D/'libexec/native_prepare.py'))
    need(definition['prepareSourceSha256']==digest(Path(__file__).read_bytes()),'Use exact installed preparation release')
    m=make_module(definition);m.identity();m.no_caps();m.installed()
    state=read_json(D/'cohort-state.json')
    module={}
    source=base64.b64decode(CONTROL_SOURCE_B64,validate=True)
    need(digest(source)==CONTROL_SOURCE_SHA,'Lifecycle control source differs')
    exec(compile(source,'<pinned-lifecycle-control>','exec'),module)
    module['validate_quiescent'](state)
    old=old_state(m)
    if mode=='activation-plan':
        need(m.properties(UNIT).get('LoadState')=='not-found','Existing new unit preserved; use health')
        pins={str(D/relative):row['sha256'] for relative,row in read_json(D/'input-manifest.json').items()}
        for name in ('config/runtime.toml','config/api-key','installation.json','definition-native.json',
                     'libexec/native_service.py','libexec/native_base.py','libexec/native_prepare.py',
                     'cli/bin/aenv-native','cli/config/aenv/credentials'):
            pins[str(D/name)]=digest(own(D/name))
        if definition['rootfsBinding']:
            pins[definition['rootfsBinding']['path']]=definition['rootfsBinding']['sha256']
        text=root_block(pins,Path('/proc/sys/kernel/random/boot_id').read_text().strip(),old,definition['apiPort'])
    else:
        props=m.properties(UNIT)
        need(props.get('ActiveState')=='active' and int(props.get('MainPID','0'))>1,'New service is not active; no partial rollback inferred')
        main=m.process_identity(int(props['MainPID']))
        proxy=read_json(RUNTIME/'host-proxy.json')
        need(proxy.get('revision')==m.REVISION,'Unknown proxy receipt')
        pins={name:digest(own(D/name,2*1024**2)) for name in
              ('config/api-key','config/runtime.toml','definition-native.json','installation.json',
               'libexec/native_service.py','libexec/native_prepare.py','libexec/native_base.py','cohort-state.json')}
        context={'node':NODE,'host':HOST,'deployment':str(D),'unit':UNIT,'port':definition['apiPort'],
                 'main':{'pid':main['pid'],'startTicks':main['start_ticks']},
                 'proxy':{'pid':proxy['pid'],'startTicks':proxy['start_ticks']},
                 'boot':Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
                 'pins':pins,'cohort':state,'preserve':old}
        text=module['rollback_root_block'](context)
    print('BEGIN_NATIVE_CONTROL_PLAN');print(text);print('END_NATIVE_CONTROL_PLAN')
    return 0


def main():
    parser=argparse.ArgumentParser(description='Prepare the A Host-file Runtime; no Guest or SDK calls.')
    parser.add_argument('mode',nargs='?',choices=('plan','prepare','activation-plan','rollback-plan','health'),default='plan')
    args=parser.parse_args();select_node('node-a')
    if args.mode=='plan':
        print(json.dumps({'status':'PLAN_ONLY','deployment':str(D),'coreCommit':COMMIT,
          'Guest_created':False,'SDK_called':False,'memfilePrivateCowImplemented':False}));return 0
    try:
        need(sys.platform=='linux' and socket.gethostname()==HOST and os.uname().machine=='aarch64','Use node A ARM64')
        need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk')
        caps=dict(x.split(':',1) for x in Path('/proc/self/status').read_text().splitlines() if ':' in x)
        need(all(int(caps[x],16)==0 for x in ('CapInh','CapPrm','CapEff','CapAmb')),'Capability-free caller required')
        if args.mode in ('activation-plan','rollback-plan'):return control_plan(args.mode)
        if args.mode=='health':
            return subprocess.run(['/usr/bin/python3','-I','-B',str(D/'libexec/native_service.py'),'health'],timeout=120).returncode
        verify_stopped_v1_plan()
        need(all(not p.exists() and not p.is_symlink() for p in (D,RUNTIME,FC_WORK,PLAN)),'Prior deployment/plan preserved')
        binding,pin=prepare_bound_inputs()
        return prepare(argparse.Namespace(node='node-a',core_report=str(ROOT/'builds/dsec-hostfile-release-v2/return.json'),
            tools_report=str(ROOT/'r/pm-a-v1/tools-runtime/return.json'),tools_image=None,
            rootfs_binding=binding,binding_sha256=pin,ordinary_only=False))
    except Exception as error:
        reason=re.sub(r'e2b_[A-Za-z0-9._~-]+','<redacted>',str(error))
        print(json.dumps({'status':'STOPPED_DSEC_DEPLOYMENT_PRESERVE_ALL_OUTPUTS','reason':reason[:1200],
            'SDK_called':False,'Guest_created':False,'partialDeployment':str(D),'partialPlan':str(PLAN)}));return 1





