def seed_existing_inputs():
    """New config files reference already snapshot-retained immutable sources."""
    report=read_json(ROOT/'builds/native-four-inputs-v1/return.json')
    need(report['status']=='FOUR_NATIVE_IMAGES_AND_BINARIES_PREPARED_NOT_DEPLOYED','Original inputs incomplete')
    cache=D/'state/image-cache'
    need(not cache.exists() and not cache.is_symlink(),'Existing cache preserved')
    cache.mkdir(mode=0o700);(cache/'configs').mkdir(mode=0o700)
    images=[]
    for i,item in enumerate(report['cases']):
        original=read_json(ROOT/('builds/native-four-inputs-v1/case-'+str(i)+'/source-config.json'))
        need(len(original['lowers'])==len(item['layers']),'Source layer count differs')
        lowers=[]
        for layer,old in zip(item['layers'],original['lowers']):
            path=Path(layer['path'])
            need(path.resolve(strict=True)==path and path.is_relative_to(BASE/'state/snapshot-store/repository/managed-layers'),
                 'Source is not retained by the original snapshot')
            info=path.stat()
            need(stat.S_ISREG(info.st_mode) and info.st_uid==1204 and info.st_size==layer['size']
                 and old['digest']==layer['digest'] and old['size']==layer['size'],'Retained source changed')
            row={'file':str(path),'digest':layer['digest'],'size':layer['size']}
            if old.get('uuid'):row['uuid']=old['uuid']
            lowers.append(row)
        source=cache/'configs'/(item['ociDigest'].replace(':','-')+'-image.json')
        data=(json.dumps({'lowers':lowers,'upper':{},'repoBlobUrl':''},indent=2)+'\n').encode()
        with source.open('xb') as out:out.write(data)
        oci=Path(item['ociDirectory'])
        need(oci.resolve(strict=True)==oci and oci.is_relative_to(ROOT) and oci.is_dir(),'Retained OCI directory missing')
        images.append({**{key:item[key] for key in ('instanceId','sourceImage','layers','ociDigest','resources','replaySha256')},
            'templateIndex':i,'sourceConfig':str(source),
            'sourceConfigSha256':digest(data),'ociReference':'ocidir://'+str(oci)+'@'+item['ociDigest']})
    receipt={'status':'FOUR_ROOTFS_INPUTS_SEEDED_NOT_GUEST_ACCEPTANCE','node':NODE,
        'coreCommit':'32ce41c0ac6436198860f888e07ef9793e58dc40','coreTree':'0e973a6e101c1a1c71b48bf70f2d910f48cd672f',
        'images':images,'databaseCopied':False,'SDK_called':False,'Guest_created':False,
        'coldCacheClaimed':False,'existingSnapshotsMustRemainRetained':True,
        'sourceLayerFilesCopied':False,'sourceLayerFilesModified':False}
    with (D/'rootfs-inputs.json').open('x') as out:json.dump(receipt,out,indent=2)

