def validate_retained_binding(item,binding,index):
    """Both producers already use the canonical sha256:<64 hex> identity."""
    prefix='Template '+str(index)+': '
    declared=item['nativeImage']
    need(isinstance(declared.get('sha256'),str) and
         re.fullmatch(r'sha256:[0-9a-f]{64}',declared['sha256']) is not None,
         prefix+'invalid declared native image digest format')
    need(type(declared.get('bytes')) is int and declared['bytes']>0,
         prefix+'invalid declared native image length')
    need(binding['sourceImage']==item['sourceImage'],prefix+'source-layer identity differs')
    spec=binding['layers'][0]
    need(spec['bytes']==declared['bytes'],prefix+'native image length differs')
    need(spec['sha256']==declared['sha256'],prefix+'native image SHA256 differs')

def verify_stopped_v1_plan():
    """Accept only the exact pre-catalog partial stage; preserve every old file."""
    old=ROOT/'r/dsec-hostfile-plan-v1'
    original=ROOT/'A_prepare_dsec_runtime_v1.py'
    need(digest(own(original,512*1024))=='9b307c35cd1c6703e3fe378a73df2885e224ad0ea4b52c02f8b982cf7867dfde',
         'Original v1 entry differs; preserved')
    need(old.resolve(strict=True)==old and old.is_dir() and old.stat().st_uid==1204,
         'Missing or redirected v1 partial plan')
    need({p.name for p in old.iterdir()}=={'aenv_ub_provider'},
         'V1 advanced beyond pre-catalog failure; preserve and inspect instead of resuming')
    package=old/'aenv_ub_provider'
    need(package.resolve(strict=True)==package and package.is_dir() and package.stat().st_uid==1204,
         'Unexpected v1 provider source directory')
    need({p.name for p in package.iterdir()}==set(PROVIDER_FILES),'Unexpected v1 partial source inventory')
    for name,row in PROVIDER_FILES.items():
        need(digest(own(package/name,1024**2))==row['sha256'],'V1 partial provider source changed')
    print('STOPPED_V1_INPUTS_VERIFIED_PRESERVED_NEW_V2_PLAN',flush=True)

if __name__=='__main__':raise SystemExit(main())
